import fs from "node:fs";
import path from "node:path";

function normalize(value) {
  return String(value || "").replace(/\\/g, "/").replace(/^\.\//, "");
}

function expandBraces(pattern) {
  const match = pattern.match(/\{([^{}]+)\}/);
  if (!match) return [pattern];
  const before = pattern.slice(0, match.index);
  const after = pattern.slice(match.index + match[0].length);
  return match[1].split(",").flatMap((item) => expandBraces(`${before}${item}${after}`));
}

function escapeRegex(char) {
  return /[\\^$+?.()|{}\[\]]/.test(char) ? `\\${char}` : char;
}

function globRegex(pattern) {
  const source = normalize(pattern);
  let out = "^";
  for (let i = 0; i < source.length; i += 1) {
    const char = source[i];
    if (char === "*") {
      if (source[i + 1] === "*") {
        i += 1;
        if (source[i + 1] === "/") {
          i += 1;
          out += "(?:.*/)?";
        } else {
          out += ".*";
        }
      } else {
        out += "[^/]*";
      }
    } else if (char === "?") {
      out += "[^/]";
    } else {
      out += escapeRegex(char);
    }
  }
  return new RegExp(`${out}$`);
}

function matchAny(relativePath, patterns) {
  const normalized = normalize(relativePath);
  return patterns.some((pattern) => globRegex(pattern).test(normalized));
}

function walk(root, ignorePatterns) {
  const files = [];
  const directories = [];
  const stack = [root];
  while (stack.length > 0) {
    const current = stack.pop();
    let entries = [];
    try {
      entries = fs.readdirSync(current, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const absolute = path.join(current, entry.name);
      const relative = normalize(path.relative(root, absolute));
      if (entry.isSymbolicLink()) continue;
      if (entry.isDirectory()) {
        if (matchAny(`${relative}/`, ignorePatterns) || matchAny(relative, ignorePatterns)) continue;
        directories.push({ absolute, relative });
        stack.push(absolute);
      } else if (entry.isFile() && !matchAny(relative, ignorePatterns)) {
        files.push({ absolute, relative });
      }
    }
  }
  return { files, directories };
}

/**
 * Package-local, dependency-free subset used by the bundled manuscript tools.
 * Supports *, **, ?, brace alternatives, cwd, absolute, nodir and ignore.
 */
export function globSync(pattern, options = {}) {
  const cwd = path.resolve(options.cwd || process.cwd());
  const patterns = (Array.isArray(pattern) ? pattern : [pattern]).flatMap((item) => expandBraces(normalize(item)));
  const ignore = (Array.isArray(options.ignore) ? options.ignore : options.ignore ? [options.ignore] : [])
    .flatMap((item) => expandBraces(normalize(item)));
  const matchers = patterns.map(globRegex);
  const inventory = walk(cwd, ignore);
  const candidates = options.nodir === false
    ? [...inventory.files, ...inventory.directories]
    : inventory.files;
  const matched = candidates
    .filter((item) => matchers.some((matcher) => matcher.test(item.relative)))
    .map((item) => options.absolute ? item.absolute : item.relative)
    .sort((a, b) => a.localeCompare(b, "en"));
  return [...new Set(matched)];
}

export default { globSync };
